import { sendingPause } from "@/lib/gmail-pause";
import "server-only";

import type { Prisma } from "@/generated/prisma/client";
import { db } from "@/lib/db";
import { resolveSubscriptionLifecycle } from "@/lib/subscription-lifecycle";
import { DAILY_EMAIL_LIMIT } from "@/lib/email-limits";
import { getRoleShortcutLimit } from "@/lib/roles";
import { AppError } from "@/lib/errors";
import { PLANS, PLAN_CONFIG_VERSION, type PlanName } from "@/lib/plans";

const entitlementUserSelect = {
  id: true,
  plan: true,
  subscriptionStatus: true,
  currentPeriodStart: true,
  currentPeriodEnd: true,
  dodoSubscriptionId: true,
  gracePeriodEnd: true,
  cancelAtPeriodEnd: true,
  planOverride: true,
  planOverrideStartsAt: true,
  planOverrideExpiresAt: true,
  grandfatheredUntil: true,
  isSuspended: true,
  deletionRequestedAt: true,
  gmailAuthorized: true,
  gmailPauseReason: true,
  gmailPauseUntil: true,
} satisfies Prisma.UserSelect;

export type EntitlementUser = Omit<
  Prisma.UserGetPayload<{
    select: typeof entitlementUserSelect;
  }>,
  "cancelAtPeriodEnd" | "gmailPauseReason" | "gmailPauseUntil"
> & {
  cancelAtPeriodEnd?: boolean;
  gmailPauseReason?: import("@/generated/prisma/enums").GmailPauseReason | null;
  gmailPauseUntil?: Date | null;
};

export type EntitlementControl = {
  gmailProjectPauseUntil?: Date | null;
  sendingEnabled: boolean;
  paidGatingEnabled: boolean;
};

export type EntitlementFeature =
  | "send"
  | "templateCreate"
  | "templateEdit"
  | "templateUse"
  | "resumeUpload"
  | "manualRepeatSend"
  | "historyShortlist"
  | "markReplied"
  | "csvImport"
  | "followUpReminders"
  | "prioritySupport"
  | "blackThemes"
  | "previewHighlightColors"
  | "recipientRoleOverride";

export type EntitlementDenial =
  | "ACCOUNT_UNAVAILABLE"
  | "ACCOUNT_SUSPENDED"
  | "SYSTEM_CONTROL_UNAVAILABLE"
  | "SENDING_DISABLED"
  | "GMAIL_PROVIDER_PAUSED"
  | "GMAIL_DOMAIN_POLICY"
  | "GMAIL_RECONNECT_REQUIRED"
  | "UPGRADE_REQUIRED"
  | "BILLING_PERIOD_UNRESOLVED";

export type EntitlementDecision =
  | { allowed: true; reason: null }
  | { allowed: false; reason: EntitlementDenial };

const denialMessages: Record<EntitlementDenial, string> = {
  ACCOUNT_UNAVAILABLE: "Account unavailable.",
  ACCOUNT_SUSPENDED: "This account is suspended.",
  SYSTEM_CONTROL_UNAVAILABLE: "Access settings are temporarily unavailable.",
  SENDING_DISABLED: "Sending is temporarily paused.",
  GMAIL_PROVIDER_PAUSED:
    "Gmail has temporarily paused sending. Your Mailloop allowance is separate.",
  GMAIL_DOMAIN_POLICY:
    "Ask your workspace administrator to allow Mailloop, then reconnect Gmail.",
  GMAIL_RECONNECT_REQUIRED: "Reconnect Gmail in Settings before sending.",
  UPGRADE_REQUIRED: "This feature requires the Paid plan.",
  BILLING_PERIOD_UNRESOLVED:
    "Sending is paused until the subscription period is verified.",
};

export class EntitlementError extends AppError {
  constructor(readonly code: EntitlementDenial) {
    super(denialMessages[code]);
    this.name = "EntitlementError";
  }
}

export function getEffectivePlan(
  user: EntitlementUser,
  now = new Date(Date.now()),
): PlanName {
  if (user.deletionRequestedAt || user.isSuspended) return "FREE";
  const time = now.getTime();
  const overrideActive =
    user.planOverride !== null &&
    user.planOverrideStartsAt !== null &&
    user.planOverrideStartsAt.getTime() <= time &&
    (user.planOverrideExpiresAt === null ||
      time < user.planOverrideExpiresAt.getTime());
  if (overrideActive) return user.planOverride!;
  if (
    user.grandfatheredUntil !== null &&
    time < user.grandfatheredUntil.getTime()
  )
    return "PAID";
  return resolveSubscriptionLifecycle(user, now).paid ? "PAID" : "FREE";
}

export function hasUnresolvedBillingPeriod(
  user: EntitlementUser,
  now = new Date(Date.now()),
) {
  return resolveSubscriptionLifecycle(user, now).unresolved;
}

export function canUser(
  user: EntitlementUser,
  feature: EntitlementFeature,
  control: EntitlementControl | null,
  now = new Date(Date.now()),
): EntitlementDecision {
  if (user.deletionRequestedAt)
    return { allowed: false, reason: "ACCOUNT_UNAVAILABLE" };
  if (user.isSuspended) return { allowed: false, reason: "ACCOUNT_SUSPENDED" };
  if (control === null)
    return { allowed: false, reason: "SYSTEM_CONTROL_UNAVAILABLE" };
  if (feature === "send") {
    if (!control.sendingEnabled)
      return { allowed: false, reason: "SENDING_DISABLED" };
    const providerPause = sendingPause(user, control, now);
    if (providerPause)
      return {
        allowed: false,
        reason:
          providerPause.code === "DOMAIN_POLICY"
            ? "GMAIL_DOMAIN_POLICY"
            : providerPause.code === "RECONNECT_REQUIRED"
              ? "GMAIL_RECONNECT_REQUIRED"
              : "GMAIL_PROVIDER_PAUSED",
      };
    if (!user.gmailAuthorized)
      return { allowed: false, reason: "GMAIL_RECONNECT_REQUIRED" };
    if (control.paidGatingEnabled && hasUnresolvedBillingPeriod(user, now))
      return { allowed: false, reason: "BILLING_PERIOD_UNRESOLVED" };
    return { allowed: true, reason: null };
  }

  const plan = PLANS[getEffectivePlan(user, now)];
  let allowed: boolean;
  switch (feature) {
    case "templateCreate":
    case "templateEdit":
    case "templateUse":
      allowed = true;
      break;
    case "resumeUpload":
      allowed = plan.resumeAttachment;
      break;
    case "recipientRoleOverride":
      allowed = plan.recipientRoleOverride;
      break;
    case "previewHighlightColors":
      allowed = plan.previewHighlightColors;
      break;
    case "blackThemes":
      allowed = plan.blackThemes;
      break;
    case "prioritySupport":
      // New feature; excluded from legacy access.
      allowed = plan.prioritySupport;
      break;
    case "historyShortlist":
    case "manualRepeatSend":
    case "markReplied":
    case "csvImport":
    case "followUpReminders":
      allowed = !control.paidGatingEnabled || plan[feature];
      break;
  }
  return allowed
    ? { allowed: true, reason: null }
    : { allowed: false, reason: "UPGRADE_REQUIRED" };
}

// Internal helper: callers authenticate first and supply their session user ID.
// Transactions preserve read context; callers own locking and resource checks.
export async function requireEntitlement(
  userId: string,
  feature: EntitlementFeature,
  tx?: Prisma.TransactionClient,
): Promise<void> {
  const client = tx ?? db;
  const user = await client.user.findUnique({
    where: { id: userId },
    select: entitlementUserSelect,
  });
  if (!user) throw new EntitlementError("ACCOUNT_UNAVAILABLE");
  const control = await client.systemControl.findUnique({
    where: { key: "global" },
    select: {
      sendingEnabled: true,
      paidGatingEnabled: true,
      gmailProjectPauseUntil: true,
    },
  });
  const decision = canUser(user, feature, control);
  if (!decision.allowed) throw new EntitlementError(decision.reason);
}

// Configured allowance sizes; usage and readiness come from the fresh ledger snapshot.
export function getClientEntitlements(
  user: EntitlementUser,
  control: EntitlementControl | null,
  now = new Date(Date.now()),
) {
  const effectivePlan = getEffectivePlan(user, now);
  const plan = PLANS[effectivePlan];
  const send = canUser(user, "send", control, now);
  const templateCreate = canUser(user, "templateCreate", control, now);
  const templateEdit = canUser(user, "templateEdit", control, now);
  const templateUse = canUser(user, "templateUse", control, now);
  const resumeUpload = canUser(user, "resumeUpload", control, now);
  const manualRepeatSend = canUser(user, "manualRepeatSend", control, now);
  const historyShortlist = canUser(user, "historyShortlist", control, now);
  const markReplied = canUser(user, "markReplied", control, now);
  const csvImport = canUser(user, "csvImport", control, now);
  const followUpReminders = canUser(user, "followUpReminders", control, now);
  const prioritySupport = canUser(user, "prioritySupport", control, now);

  const previewHighlightColors = canUser(
    user,
    "previewHighlightColors",
    control,
    now,
  );
  const recipientRoleOverride = canUser(
    user,
    "recipientRoleOverride",
    control,
    now,
  );
  const blackThemes = canUser(user, "blackThemes", control, now);

  const pause = sendingPause(user, control, now);
  return {
    gmailPause: pause
      ? { code: pause.code, until: pause.until?.toISOString() ?? null }
      : null,
    effectivePlan,
    accessDeadline:
      [
        user.currentPeriodEnd,
        user.gracePeriodEnd,
        user.planOverrideStartsAt,
        user.planOverrideExpiresAt,
        user.grandfatheredUntil,
      ]
        .filter((date): date is Date => Boolean(date && date > now))
        .sort((a, b) => +a - +b)[0]
        ?.toISOString() ?? null,
    planConfigVersion: PLAN_CONFIG_VERSION,
    paidGatingEnabled: control?.paidGatingEnabled ?? false,
    controlsAvailable: control !== null,
    limits: {
      roleShortcuts: getRoleShortcutLimit(effectivePlan),
      monthlyEmails: control?.paidGatingEnabled ? plan.monthlyEmails : null,
      dailyEmails: control?.paidGatingEnabled
        ? plan.dailyEmails
        : DAILY_EMAIL_LIMIT,
      campaignRecipients: control?.paidGatingEnabled
        ? plan.campaignRecipients
        : PLANS.PAID.campaignRecipients,
      savedTemplates: control?.paidGatingEnabled ? plan.savedTemplates : null,
    },
    tracking: plan.tracking,
    features: {
      send: send.allowed,
      templateCreate: templateCreate.allowed,
      templateEdit: templateEdit.allowed,
      templateUse: templateUse.allowed,
      resumeAttachment: resumeUpload.allowed,
      manualRepeatSend: manualRepeatSend.allowed,
      historyShortlist: historyShortlist.allowed,
      markReplied: markReplied.allowed,
      csvImport: csvImport.allowed,
      followUpReminders: followUpReminders.allowed,
      prioritySupport: prioritySupport.allowed,
      blackThemes: blackThemes.allowed,
      previewHighlightColors: previewHighlightColors.allowed,
      recipientRoleOverride: recipientRoleOverride.allowed,
    },
    followUpDelayOptions: followUpReminders.allowed
      ? [...PLANS.PAID.followUpDelayOptions]
      : [],
    reasons: {
      send: send.reason,
      templateCreate: templateCreate.reason,
      templateEdit: templateEdit.reason,
      templateUse: templateUse.reason,
      resumeUpload: resumeUpload.reason,
      manualRepeatSend: manualRepeatSend.reason,
      historyShortlist: historyShortlist.reason,
      markReplied: markReplied.reason,
      csvImport: csvImport.reason,
      followUpReminders: followUpReminders.reason,
      prioritySupport: prioritySupport.reason,
      blackThemes: blackThemes.reason,
      previewHighlightColors: previewHighlightColors.reason,
      recipientRoleOverride: recipientRoleOverride.reason,
    },
  };
}

export type ClientEntitlements = ReturnType<typeof getClientEntitlements>;

export async function readEntitlements(
  userId: string,
  tx?: Prisma.TransactionClient,
) {
  const client = tx ?? db;
  const user = await client.user.findUnique({
    where: { id: userId },
    select: entitlementUserSelect,
  });
  if (!user) throw new EntitlementError("ACCOUNT_UNAVAILABLE");
  const control = await client.systemControl.findUnique({
    where: { key: "global" },
    select: {
      sendingEnabled: true,
      paidGatingEnabled: true,
      gmailProjectPauseUntil: true,
    },
  });
  return getClientEntitlements(user, control);
}
